// YouTube: the site owner's playlist of sage videos (English, Russian, a few Hebrew) and the
// introduction video of the site. public/data-youtube.json is generated by
// scripts/build_youtube_links.py, keyed by sage id. Bundled at build time, so a page makes no
// request to YouTube until the visitor presses play.
import youtubeData from '../public/data-youtube.json'
import type { Locale } from './types'

export interface SageVideo {
  /** YouTube video id. */
  id: string
  /** The video's own title, in the video's language (YouTube's snippet.title, not the translation a viewer sees). */
  title: string
  seconds: number
}

export interface YoutubeEntry {
  /** The roster label this entry was made for; guards against ids drifting. */
  label: string
  /** The sage's videos in that language, in playlist order. */
  he?: SageVideo[]
  en?: SageVideo[]
  ru?: SageVideo[]
}

const entries = (youtubeData as unknown as { sages: Record<string, YoutubeEntry> }).sages

export function getYoutubeEntry(sageId: string): YoutubeEntry | undefined {
  return entries[sageId]
}

export function youtubeEntries(): Array<[string, YoutubeEntry]> {
  return Object.entries(entries)
}

/** The sage's videos in the page's language, or none: a video is never shown in another language. */
export function sageVideos(sageId: string, locale: Locale): SageVideo[] {
  return entries[sageId]?.[locale] ?? []
}

/** A YouTube video id is 11 characters of letters, digits, "-" and "_". */
export const isVideoId = (id: string) => /^[A-Za-z0-9_-]{11}$/.test(id)

/**
 * The site's introduction video, one upload per language. A language without an entry shows no
 * video. Replace the entry when the video is uploaded again: YouTube gives a new upload a new id.
 */
export const INTRO_VIDEO: Record<Locale, SageVideo | null> = {
  he: { id: 'uf4X20K1pq0', title: 'אוצר חכמים - כנסו, חפשו, גלו!', seconds: 0 },
  en: { id: 'ZbVfjEiNg6s', title: 'Otzar Hahachamim - Come in, search, discover!', seconds: 0 },
  ru: { id: '9u__eJAvb9s', title: 'Оцар Хахамим - Заходите, ищите, открывайте!', seconds: 0 },
}

export const watchUrl = (id: string) => `https://www.youtube.com/watch?v=${id}`

/** The embed address: youtube-nocookie.com sets no cookie until the viewer plays. */
export const embedUrl = (id: string, locale: Locale) =>
  `https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0&hl=${locale}&cc_lang_pref=${locale}`

export function durationLabel(seconds: number): string {
  if (!seconds || seconds < 1) return ''
  const m = Math.floor(seconds / 60)
  const s = Math.round(seconds % 60)
  return `${m}:${String(s).padStart(2, '0')}`
}
